public final class Config {
    private static volatile Config instance;
    public static Config instance() {
        Config local = instance;                  // volatile read on the hot path
        if (local == null) {
            synchronized (Config.class) {         // lock only while constructing
                if (instance == null) instance = local = new Config();
            }
        }
        return local;
    }
}
